'use client';
import { useState } from 'react';
import Navbar from '@/components/Navbar';
import { Search, MapPin, Star, Phone } from 'lucide-react';

const MOCK_HOSPITALS = [
  { id: 1, name: 'Grand City Hospital', location: 'Andheri West, Mumbai', rating: 4.8, discount: 'Up to 40% OFF', distance: '2.5 km', image: 'linear-gradient(45deg, #1e293b, #0f172a)' },
  { id: 2, name: 'Apex Multi-Specialty', location: 'Bandra, Mumbai', rating: 4.5, discount: 'Flat 20% OFF', distance: '5.0 km', image: 'linear-gradient(45deg, #334155, #1e293b)' },
  { id: 3, name: 'City Care Centre', location: 'Juhu, Mumbai', rating: 4.2, discount: '15% OFF on OPD', distance: '1.2 km', image: 'linear-gradient(45deg, #475569, #334155)' },
  { id: 4, name: 'Global Health Institute', location: 'Goregaon, Mumbai', rating: 4.9, discount: 'Free First Consult', distance: '8.0 km', image: 'linear-gradient(45deg, #0f172a, #1e293b)' },
];

export default function Hospitals() {
  const [searchTerm, setSearchTerm] = useState('');

  const filteredHospitals = MOCK_HOSPITALS.filter(h => 
    h.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
    h.location.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <main style={{ paddingBottom: '100px' }}>
      <Navbar />
      
      <div className="container" style={{ paddingTop: 'calc(var(--header-height) + 2rem)' }}>
        
        {/* Header & Search */}
        <div style={{ marginBottom: '2rem' }}>
          <h1 style={{ marginBottom: '1rem' }}>Find Hospitals</h1>
          <div className="glass" style={{ display: 'flex', gap: '1rem', padding: '1rem', alignItems: 'center' }}>
             <MapPin size={20} color="var(--primary)" />
             <input 
                type="text"
                placeholder="Search by hospital name or location..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                style={{ background: 'transparent', border: 'none', color: '#fff', fontSize: '1rem', outline: 'none', flex: 1 }}
             />
             <button className="btn btn-primary">Search</button>
          </div>
        </div>

        {/* Listings */}
        <div className="grid-cards">
          {filteredHospitals.map((hospital) => (
             <div key={hospital.id} className="glass" style={{ padding: '0', overflow: 'hidden', cursor: 'pointer', transition: 'transform 0.2s' }}>
                <div style={{ height: '200px', background: hospital.image, position: 'relative' }}>
                   <div style={{ position: 'absolute', top: '10px', left: '10px', background: 'rgba(0,0,0,0.6)', color: '#fff', padding: '4px 8px', borderRadius: '6px', fontSize: '0.8rem', display: 'flex', alignItems: 'center', gap: '4px' }}>
                      <Star size={12} fill="#fbbf24" stroke="none" /> {hospital.rating}
                   </div>
                </div>
                
                <div style={{ padding: '1.5rem' }}>
                    <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '0.5rem' }}>
                        <h3 style={{ fontSize: '1.3rem' }}>{hospital.name}</h3>
                    </div>
                    
                    <p style={{ color: 'var(--text-muted)', fontSize: '0.9rem', marginBottom: '1rem', display: 'flex', alignItems: 'center', gap: '6px' }}>
                       <MapPin size={14} /> {hospital.location} • {hospital.distance}
                    </p>

                    <div style={{ background: 'rgba(255, 159, 67, 0.1)', color: 'var(--accent)', padding: '10px', borderRadius: '8px', marginBottom: '1.5rem', textAlign: 'center', fontWeight: 'bold', fontSize: '0.95rem' }}>
                        {hospital.discount}
                    </div>

                    <div style={{ display: 'flex', gap: '1rem' }}>
                        <button className="btn btn-outline" style={{ flex: 1 }}>Details</button>
                        <button className="btn btn-primary" style={{ flex: 1 }}>Book Now</button>
                    </div>
                </div>
             </div>
          ))}
        </div>

      </div>
    </main>
  );
}
